# Move to the FlashcardApp project directory Set-Location $PSScriptRoot
# Step 1: Build Docker image and run tests Write-Host "Building Docker image and running tests..."
docker build --no-cache -t flashcardapp:lab1 .
# Step 2: Only continue if Docker tests passed if ($LASTEXITCODE -ne 0) { Write-Host "Tests failed! WPF application will not launch." exit 1 }
Write-Host "Docker tests passed!"
# Step 3: Build the latest WPF application dotnet build .\FlashcardApp.WpfUI\FlashcardApp.WpfUI.csproj --configuration Debug
if ($LASTEXITCODE -ne 0) { Write-Host "WPF build failed!" exit 1 }
# Step 4: Locate the WPF executable $exePath = "C:\Users\Admin123\Documents\Rider Projects\FlashcardApp\FlashcardApp.WpfUI\bin\Debug\net9.0-windows\FlashcardApp.WpfUI.exe"
# Step 5: Launch the WPF application if (Test-Path $exePath) { Write-Host "Launching FlashcardApp WPF..." Start-Process -FilePath $exePath -WorkingDirectory (Split-Path -Parent $exePath) } else { Write-Host "WPF executable not found!" exit 1 }

# Move to the repository root. Set-Location $PSScriptRoot $repoRoot = Split-Path -Parent $PSScriptRoot Set-Location $repoRoot
$envFile = ".env.dev" $composeFile = "docker-compose.yml"
Write-Host "Starting Docker services for development..." docker compose --env-file $envFile -f $composeFile up -d --build if ($LASTEXITCODE -ne 0) { Write-Host "Docker compose failed." exit 1 }
Write-Host "Building the WPF desktop app locally..." dotnet build .\FlashcardApp.WpfUI\FlashcardApp.WpfUI.csproj --configuration Debug if ($LASTEXITCODE -ne 0) { Write-Host "WPF build failed!" exit 1 }
$exePath = Join-Path $repoRoot "FlashcardApp.WpfUI\bin\Debug\net9.0-windows\FlashcardApp.WpfUI.exe" if (-not (Test-Path $exePath)) { Write-Host "WPF executable not found at: $exePath" exit 1 }
Write-Host "Launching WPF app..." Start-Process -FilePath $exePath -WorkingDirectory (Split-Path -Parent $exePath)
Write-Host "Dev stack is running." Write-Host "API: http://localhost:8080" Write-Host "Postgres: localhost:5432"

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/", () => "Flashcard API is running");

app.Run();

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<FlashcardApp.Core.Interfaces.IUserRepository>(sp =>
{
    var connectionString = builder.Configuration.GetConnectionString("Default");

    if (!string.IsNullOrWhiteSpace(connectionString))
    {
        return new FlashcardApp.Core.Repositories.PostgresUserRepository(connectionString);
    }

    var dataDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "FlashcardApp");
    var filePath = Path.Combine(dataDir, "users.json");
    return new FlashcardApp.Core.Repositories.JsonFileUserRepository(filePath);
});

builder.Services.AddSingleton<FlashcardApp.Core.Services.UserService>();

var app = builder.Build();

app.MapGet("/", () => "Flashcard API is running");

app.Run();

